def explore_workspace():
    """Find co-marketing guidelines and understand the workspace layout."""
    out = []

    # Look for co-marketing guidelines
    for pattern in ["*co*market*", "*partner*", "*guideline*", "*skill*", "*workflow*"]:
        try:
            res = tools.glob(pattern)
            if res:
                out.append(f"{pattern}: {res}")
        except:
            pass

    # List root directory
    try:
        out.append(f"ROOT: {tools.list_dir()}")
    except Exception as e:
        out.append(f"list_dir root failed: {e}")

    # Look for SKILL.md files
    try:
        res = tools.glob("**/SKILL.md")
        if res:
            out.append(f"SKILL.md files: {res}")
    except:
        pass

    # Look for .md files that might be guidelines
    try:
        res = tools.glob("**/*.md")
        if res:
            out.append(f"Markdown files: {res[:20]}")
    except:
        pass

    return "\n".join(out)

return explore_workspace()

